CREATE POLICY "Premium support requires eligible plan" ON public.support_requests AS RESTRICTIVE FOR INSERT TO authenticated WITH CHECK (public.is_system_admin(auth.uid()) OR (user_id = auth.uid() AND public.is_user_tenant_member(auth.uid(), tenant_id) AND EXISTS (SELECT 1 FROM public.tenants t WHERE t.id = support_requests.tenant_id AND t.is_active = true AND t.tier IN ('business', 'enterprise'))));
COMMENT ON POLICY "Premium support requires eligible plan" ON public.support_requests IS 'Restrictive plan gate applies even when owner/admin ALL policies permit inserts; existing support history is unaffected.';